23	func (a *configAdapter) Provider(name string) (fizeau.ServiceProviderEntry, bool) {
24		pc, ok := a.cfg.GetProvider(name)
25		if !ok {
26			return fizeau.ServiceProviderEntry{}, false
27		}
28		endpoints := make([]fizeau.ServiceProviderEndpoint, 0, len(pc.Endpoints))
29		for _, endpoint := range pc.Endpoints {
30			endpoints = append(endpoints, fizeau.ServiceProviderEndpoint{
31				Name:    endpoint.Name,
32				BaseURL: endpoint.BaseURL,
33			})
34		}
35		return fizeau.ServiceProviderEntry{
36			Type:      pc.Type,
37			BaseURL:   pc.BaseURL,
38			Endpoints: endpoints,
39			APIKey:    pc.APIKey,
40			Model:     pc.Model,
41		}, true
42	}
