44	func (a *configAdapter) ModelRouteNames() []string { return a.cfg.ModelRouteNames() }
45	
46	func (a *configAdapter) ModelRouteCandidates(routeName string) []string {
47		rc, ok := a.cfg.GetModelRoute(routeName)
48		if !ok {
49			return nil
50		}
51		providers := make([]string, 0, len(rc.Candidates))
52		for _, c := range rc.Candidates {
53			providers = append(providers, c.Provider)
54		}
55		return providers
56	}
57	
58	func (a *configAdapter) ModelRouteConfig(routeName string) fizeau.ServiceModelRouteConfig {
59		rc, ok := a.cfg.GetModelRoute(routeName)
60		if !ok {
61			return fizeau.ServiceModelRouteConfig{}
62		}
63		entries := make([]fizeau.ServiceRouteCandidateEntry, 0, len(rc.Candidates))
64		for _, c := range rc.Candidates {
65			entries = append(entries, fizeau.ServiceRouteCandidateEntry{
66				Provider: c.Provider,
67				Model:    c.Model,
68				Priority: c.Priority,
69			})
70		}
71		return fizeau.ServiceModelRouteConfig{
72			Strategy:   rc.Strategy,
73			Candidates: entries,
74		}
75	}
