555	func readMatrixLock(path string) (matrixLock, error) {
556		data, err := os.ReadFile(path) // #nosec G304 -- path is a runner-owned lock path
557		if err != nil {
558			return matrixLock{}, err
559		}
560		var lock matrixLock
561		if err := json.Unmarshal(data, &lock); err != nil {
562			return matrixLock{}, err
563		}
564		return lock, nil
565	}
