2	
3	import (
4		"bufio"
5		"fmt"
6		"io"
7		"io/fs"
8		"os"
9		"path/filepath"
10		"regexp"
11		"sort"
12		"strings"
13	)
14	
15	type Finding struct {
16		Path    string
17		Line    int
18		Column  int
19		Surface string
20		Match   string
21	}
22	
23	type Options struct {
24		Root string
25		Out  io.Writer
26	}
27	
28	type rule struct {
29		surface string
30		re      *regexp.Regexp
31		rootGo  bool
32	}
33	
34	var rules = []rule{
35		{surface: "github.com/DocumentDrivenDX/agent", re: regexp.MustCompile(regexp.QuoteMeta("github.com/DocumentDrivenDX/agent"))},
36		{surface: "root package agent", re: regexp.MustCompile(`^\s*package\s+agent\s*$`), rootGo: true},
37		{surface: "ddx-agent", re: regexp.MustCompile(regexp.QuoteMeta("ddx-agent"))},
38		{surface: "DDX Agent/DDx Agent", re: regexp.MustCompile(`DD[Xx] Agent`)},
39		{surface: ".agent", re: regexp.MustCompile(`(^|[^A-Za-z0-9_])\.agent([^A-Za-z0-9_]|$)`)},
40		{surface: "~/.config/agent", re: regexp.MustCompile(regexp.QuoteMeta("~/.config/agent"))},
41		{surface: "AGENT_*/DDX_AGENT_*", re: regexp.MustCompile(`\b(?:DDX_AGENT|AGENT)_[A-Z0-9_]+\b`)},
42	}
43	
44	var skippedDirs = map[string]bool{
45		".git":                 true,
46		".ddx":                 true,
47		".agents":              true,
48		".claude":              true,
49		".helix-ratchets":      true,
50		"docs/helix":           true,
51		"docs/research":        true,
52		"internal/renamecheck": true,
53	}
54	
55	var skippedFiles = map[string]bool{
56		"CHANGELOG.md": true,
57	}
58	
59	func Scan(opts Options) ([]Finding, error) {
60		root := opts.Root
61		if root == "" {
62			root = "."
63		}
64	
65		var findings []Finding
66		err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
67			if err != nil {
68				return err
69			}
70			rel, err := filepath.Rel(root, path)
71			if err != nil {
72				return err
73			}
74			rel = filepath.ToSlash(rel)
75			if rel == "." {
76				return nil
77			}
78			if d.IsDir() {
79				if shouldSkipDir(rel) {
80					return filepath.SkipDir
81				}
82				return nil
83			}
84			if skippedFiles[rel] {
85				return nil
86			}
87			if !isTextCandidate(rel) {
88				return nil
89			}
90			fileFindings, err := scanFile(root, rel)
91			if err != nil {
92				return err
93			}
94			findings = append(findings, fileFindings...)
95			return nil
96		})
97		if err != nil {
98			return nil, err
99		}
100		sort.Slice(findings, func(i, j int) bool {
101			if findings[i].Path != findings[j].Path {
102				return findings[i].Path < findings[j].Path
103			}
104			if findings[i].Line != findings[j].Line {
105				return findings[i].Line < findings[j].Line
106			}
107			return findings[i].Column < findings[j].Column
108		})
109		return findings, nil
110	}
111	
112	func Report(w io.Writer, findings []Finding) error {
113		if w == nil {
114			return nil
115		}
116		if len(findings) == 0 {
117			_, err := fmt.Fprintln(w, "rename-noise: no unallowlisted old-name hits found")
118			return err
119		}
120		if _, err := fmt.Fprintf(w, "rename-noise: %d unallowlisted old-name hit(s)\n", len(findings)); err != nil {
121			return err
122		}
123		for _, f := range findings {
124			if _, err := fmt.Fprintf(w, "%s:%d:%d: %s: %q\n", f.Path, f.Line, f.Column, f.Surface, f.Match); err != nil {
125				return err
126			}
127		}
128		return nil
129	}
130	
131	func Run(opts Options) ([]Finding, error) {
132		findings, err := Scan(opts)
133		if err != nil {
134			return nil, err
135		}
136		return findings, Report(opts.Out, findings)
137	}
138	
139	func scanFile(root, rel string) ([]Finding, error) {
140		file, err := os.Open(filepath.Join(root, filepath.FromSlash(rel)))
141		if err != nil {
142			return nil, err
143		}
144		defer file.Close()
145	
146		var findings []Finding
147		scanner := bufio.NewScanner(file)
148		buf := make([]byte, 0, 64*1024)
149		scanner.Buffer(buf, 1024*1024)
150		lineNo := 0
151		for scanner.Scan() {
152			lineNo++
153			line := scanner.Text()
154			for _, r := range rules {
155				if r.rootGo && !isRootGoFile(rel) {
156					continue
157				}
158				loc := r.re.FindStringIndex(line)
159				if loc == nil {
160					continue
161				}
162				findings = append(findings, Finding{
163					Path:    rel,
164					Line:    lineNo,
165					Column:  loc[0] + 1,
166					Surface: r.surface,
167					Match:   line[loc[0]:loc[1]],
168				})
169			}
170		}
171		return findings, scanner.Err()
172	}
173	
174	func shouldSkipDir(rel string) bool {
175		if skippedDirs[rel] {
176			return true
177		}
178		for dir := range skippedDirs {
179			if strings.HasPrefix(rel, dir+"/") {
180				return true
181			}
182		}
183		return false
184	}
185	
186	func isRootGoFile(rel string) bool {
187		return filepath.Dir(rel) == "." && strings.HasSuffix(rel, ".go")
188	}
189	
190	func isTextCandidate(rel string) bool {
191		base := filepath.Base(rel)
192		if strings.HasPrefix(base, ".") && base != ".env" {
193			return false
194		}
195		switch filepath.Ext(rel) {
196		case ".go", ".md", ".txt", ".yaml", ".yml", ".json", ".jsonl", ".toml", ".sh", ".py", ".env":
197			return true
198		default:
199			return base == "Makefile" || base == "Dockerfile" || base == "go.mod"
200		}
201	}
