1	package main
2	
3	import (
4		"context"
5		"encoding/json"
6		"fmt"
7		"os"
8	
9		fizeau "github.com/DocumentDrivenDX/fizeau"
10		agentConfig "github.com/DocumentDrivenDX/fizeau/internal/config"
11	)
12	
13	// Candidate is one (harness, provider, model) triple discovered from config.
14	type Candidate struct {
15		Harness   string `json:"harness"`
16		Provider  string `json:"provider,omitempty"`
17		Model     string `json:"model,omitempty"`
18		CostClass string `json:"cost_class,omitempty"`
19		Available bool   `json:"available"`
20	}
21	
22	// discoverCandidates enumerates available harnesses and, for provider-backed
23	// harnesses, the configured models. It creates a FizeauService via fizeau.New with
24	// the loaded ServiceConfig and calls ListHarnesses + ListModels per
25	// CONTRACT-003.
26	func discoverCandidates(wd string) ([]Candidate, error) {
27		cfg, err := agentConfig.Load(wd)
28		if err != nil {
29			return nil, fmt.Errorf("load config: %w", err)
30		}
31	
32		svc, err := fizeau.New(fizeau.ServiceOptions{
33			ServiceConfig: &configAdapter{cfg: cfg, workDir: wd},
34		})
35		if err != nil {
36			return nil, fmt.Errorf("new service: %w", err)
37		}
38	
39		ctx := context.Background()
40	
41		harnesses, err := svc.ListHarnesses(ctx)
42		if err != nil {
43			return nil, fmt.Errorf("list harnesses: %w", err)
44		}
45	
46		// Build one candidate per available subprocess-style harness (claude, codex, etc.).
47		var candidates []Candidate
48		for _, h := range harnesses {
49			if !h.Available {
50				continue
51			}
52			// "subprocess" harnesses are billed through subscription or local binary;
53			// add a single candidate with no explicit model.
54			if h.Type == "subprocess" {
55				candidates = append(candidates, Candidate{
56					Harness:   h.Name,
57					CostClass: h.CostClass,
58					Available: true,
59				})
60				continue
61			}
62			// "native" harnesses are provider-backed; enumerate per-provider models.
63			models, err := svc.ListModels(ctx, fizeau.ModelFilter{
64				Harness: h.Name,
65			})
66			if err != nil || len(models) == 0 {
67				// Surface the harness even if model listing fails.
68				candidates = append(candidates, Candidate{
69					Harness:   h.Name,
70					CostClass: h.CostClass,
71					Available: true,
72				})
73				continue
74			}
75			for _, m := range models {
76				candidates = append(candidates, Candidate{
77					Harness:   h.Name,
78					Provider:  m.Provider,
79					Model:     m.ID,
80					CostClass: h.CostClass,
81					Available: m.Available,
82				})
83			}
84		}
85	
86		return candidates, nil
87	}
88	
89	// cmdDiscover implements the 'discover' subcommand.
90	func cmdDiscover(args []string) int {
91		fs := flagSet("discover")
92		jsonOut := fs.Bool("json", false, "Emit JSON array instead of table")
93		workDir := fs.String("work-dir", "", "Agent working directory (default: cwd)")
94		if err := fs.Parse(args); err != nil {
95			return 2
96		}
97	
98		wd := resolveWorkDir(*workDir)
99		candidates, err := discoverCandidates(wd)
100		if err != nil {
101			fmt.Fprintf(os.Stderr, "%s discover: %v\n", benchCommandName(), err)
102			return 1
103		}
104	
105		if *jsonOut {
106			data, _ := json.MarshalIndent(candidates, "", "  ")
107			fmt.Println(string(data))
108			return 0
109		}
110	
111		// Tabular output.
112		if len(candidates) == 0 {
113			fmt.Println("No candidates discovered. Check agent config.")
114			return 0
115		}
116		fmt.Printf("%-16s %-20s %-40s %-10s\n", "HARNESS", "PROVIDER", "MODEL", "COST_CLASS")
117		fmt.Printf("%-16s %-20s %-40s %-10s\n", "-------", "--------", "-----", "----------")
118		for _, c := range candidates {
119			fmt.Printf("%-16s %-20s %-40s %-10s\n", c.Harness, c.Provider, c.Model, c.CostClass)
120		}
121		return 0
122	}
